code2='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    fill_by_size = {5: 8, 7: 4, 9: 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            top = min(y for y, x in component)
            bottom = max(y for y, x in component)
            left = min(x for y, x in component)
            right = max(x for y, x in component)
            height, width = bottom-top+1, right-left+1
            if height != width or height not in fill_by_size:
                continue
            border = all(grid[top][x] == 2 and grid[bottom][x] == 2 for x in range(left,right+1))
            border = border and all(grid[y][left] == 2 and grid[y][right] == 2 for y in range(top,bottom+1))
            if border:
                color = fill_by_size[height]
                for y in range(top+1,bottom):
                    for x in range(left+1,right):
                        if out[y][x] == 0:
                            out[y][x] = color
    return out
